{"content":"<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>邮箱登录 Demo</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            min-height: 100vh;
            display: flex;
            justify-content: center;
            align-items: center;
            padding: 20px;
        }

        .container {
            width: 100%;
            max-width: 375px;
        }

        .login-box {
            background: #fff;
            border-radius: 12px;
            padding: 32px 24px;
            box-shadow: 0 10px 40px rgba(0, 0, 0, 0.2);
        }

        .login-header {
            text-align: center;
            margin-bottom: 32px;
        }

        .login-header h1 {
            font-size: 24px;
            color: #333;
            margin-bottom: 8px;
        }

        .login-header p {
            font-size: 14px;
            color: #666;
        }

        .form-group {
            margin-bottom: 20px;
        }

        .form-group label {
            display: block;
            font-size: 14px;
            color: #333;
            margin-bottom: 8px;
            font-weight: 500;
        }

        .form-group input {
            width: 100%;
            padding: 12px 16px;
            font-size: 16px;
            border: 1px solid #ddd;
            border-radius: 8px;
            outline: none;
            transition: border-color 0.3s, box-shadow 0.3s;
        }

        .form-group input:focus {
            border-color: #667eea;
            box-shadow: 0 0 0 3px rgba(102, 126, 234, 0.1);
        }

        .form-group input.error {
            border-color: #e74c3c;
        }

        .error-message {
            color: #e74c3c;
            font-size: 13px;
            margin-top: 6px;
            display: none;
        }

        .error-message.show {
            display: block;
        }

        .login-btn {
            width: 100%;
            padding: 14px;
            font-size: 16px;
            font-weight: 600;
            color: #fff;
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            border: none;
            border-radius: 8px;
            cursor: pointer;
            transition: transform 0.2s, box-shadow 0.2s;
        }

        .login-btn:hover {
            transform: translateY(-1px);
            box-shadow: 0 4px 12px rgba(102, 126, 234, 0.4);
        }

        .login-btn:active {
            transform: translateY(0);
        }

        .login-btn:disabled {
            opacity: 0.6;
            cursor: not-allowed;
            transform: none;
        }

        /* 登录成功后的欢迎页面 */
        .welcome-box {
            display: none;
            text-align: center;
        }

        .welcome-box.show {
            display: block;
        }

        .welcome-icon {
            width: 80px;
            height: 80px;
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            margin: 0 auto 24px;
        }

        .welcome-icon svg {
            width: 40px;
            height: 40px;
            fill: #fff;
        }

        .welcome-box h1 {
            font-size: 24px;
            color: #333;
            margin-bottom: 12px;
        }

        .welcome-box p {
            font-size: 16px;
            color: #666;
            margin-bottom: 32px;
        }

        .welcome-box .email-display {
            background: #f5f5f5;
            padding: 12px 16px;
            border-radius: 8px;
            margin-bottom: 24px;
            font-size: 14px;
            color: #333;
            word-break: break-all;
        }

        .logout-btn {
            width: 100%;
            padding: 14px;
            font-size: 16px;
            font-weight: 600;
            color: #667eea;
            background: #fff;
            border: 2px solid #667eea;
            border-radius: 8px;
            cursor: pointer;
            transition: background 0.2s, color 0.2s;
        }

        .logout-btn:hover {
            background: #667eea;
            color: #fff;
        }

        /* 隐藏登录表单 */
        .login-box.has-logged-in {
            display: none;
        }

        /* Demo 提示 */
        .demo-hint {
            margin-top: 20px;
            padding: 12px;
            background: #f0f0f0;
            border-radius: 8px;
            font-size: 12px;
            color: #666;
            text-align: center;
        }

        .demo-hint strong {
            color: #333;
        }
    </style>
</head>
<body>
    <div class="container">
        <!-- 登录表单 -->
        <div class="login-box" id="loginBox">
            <div class="login-header">
                <h1>邮箱登录</h1>
                <p>欢迎回来，请登录您的账号</p>
            </div>

            <form id="loginForm">
                <div class="form-group">
                    <label for="email">邮箱地址</label>
                    <input type="email" id="email" name="email" placeholder="请输入邮箱地址" autocomplete="email">
                    <div class="error-message" id="emailError"></div>
                </div>

                <div class="form-group">
                    <label for="password">密码</label>
                    <input type="password" id="password" name="password" placeholder="请输入密码" autocomplete="current-password">
                    <div class="error-message" id="passwordError"></div>
                </div>

                <div class="error-message show" id="loginError" style="margin-bottom: 20px; text-align: center;"></div>

                <button type="submit" class="login-btn" id="loginBtn">登录</button>
            </form>

            <div class="demo-hint">
                <strong>Demo 账号：</strong>demo@example.test<br>
                <strong>密码：</strong>DemoPass2026
            </div>
        </div>

        <!-- 登录成功欢迎页 -->
        <div class="login-box welcome-box" id="welcomeBox">
            <div class="welcome-icon">
                <svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
                    <path d="M9 16.17L4.83 12l-1.42 1.41L9 19 21 7l-1.41-1.41L9 16.17z"/>
                </svg>
            </div>
            <h1>登录成功！</h1>
            <p>欢迎使用 Demo 系统</p>
            <div class="email-display" id="userEmail"></div>
            <button class="logout-btn" id="logoutBtn">退出登录</button>
        </div>
    </div>

    <script>
        // 常量配置
        const DEMO_EMAIL = 'demo@example.test';
        const DEMO_PASSWORD = 'DemoPass2026';
        const STORAGE_KEY = 's5_fresh_login_b_logged_in';
        const USER_EMAIL_KEY = 's5_fresh_login_b_user_email';

        // DOM 元素
        const loginBox = document.getElementById('loginBox');
        const welcomeBox = document.getElementById('welcomeBox');
        const loginForm = document.getElementById('loginForm');
        const emailInput = document.getElementById('email');
        const passwordInput = document.getElementById('password');
        const loginBtn = document.getElementById('loginBtn');
        const loginError = document.getElementById('loginError');
        const emailError = document.getElementById('emailError');
        const passwordError = document.getElementById('passwordError');
        const userEmailDisplay = document.getElementById('userEmail');
        const logoutBtn = document.getElementById('logoutBtn');

        // 初始化：检查登录状态
        function init() {
            const isLoggedIn = localStorage.getItem(STORAGE_KEY) === 'true';
            const savedEmail = localStorage.getItem(USER_EMAIL_KEY);

            if (isLoggedIn && savedEmail) {
                showWelcomePage(savedEmail);
            } else {
                showLoginPage();
            }
        }

        // 显示登录页面
        function showLoginPage() {
            loginBox.classList.remove('has-logged-in');
            welcomeBox.classList.remove('show');
            clearErrors();
        }

        // 显示欢迎页面
        function showWelcomePage(email) {
            loginBox.classList.add('has-logged-in');
            welcomeBox.classList.add('show');
            userEmailDisplay.textContent = email;
            // 恢复表单输入
            emailInput.value = email;
        }

        // 清除错误提示
        function clearErrors() {
            emailError.textContent = '';
            emailError.classList.remove('show');
            passwordError.textContent = '';
            passwordError.classList.remove('show');
            loginError.textContent = '';
            loginError.classList.remove('show');
            emailInput.classList.remove('error');
            passwordInput.classList.remove('error');
        }

        // 验证邮箱格式
        function validateEmail(email) {
            const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
            return emailRegex.test(email);
        }

        // 处理登录
        function handleLogin(e) {
            e.preventDefault();
            clearErrors();

            const email = emailInput.value.trim();
            const password = passwordInput.value;

            // 验证邮箱
            if (!email) {
                showFieldError(emailInput, emailError, '请输入邮箱地址');
                return;
            }

            if (!validateEmail(email)) {
                showFieldError(emailInput, emailError, '请输入有效的邮箱地址');
                return;
            }

            // 验证密码
            if (!password) {
                showFieldError(passwordInput, passwordError, '请输入密码');
                return;
            }

            // 验证凭据
            if (email === DEMO_EMAIL && password === DEMO_PASSWORD) {
                // 登录成功，保存状态
                localStorage.setItem(STORAGE_KEY, 'true');
                localStorage.setItem(USER_EMAIL_KEY, email);
                showWelcomePage(email);
            } else {
                // 登录失败
                showLoginError('邮箱或密码错误，请重试');
            }
        }

        // 显示字段错误
        function showFieldError(input, errorEl, message) {
            input.classList.add('error');
            errorEl.textContent = message;
            errorEl.classList.add('show');
        }

        // 显示登录错误
        function showLoginError(message) {
            loginError.textContent = message;
            loginError.classList.add('show');
        }

        // 处理退出登录
        function handleLogout() {
            localStorage.removeItem(STORAGE_KEY);
            localStorage.removeItem(USER_EMAIL_KEY);
            passwordInput.value = '';
            showLoginPage();
        }

        // 事件绑定
        loginForm.addEventListener('submit', handleLogin);
        logoutBtn.addEventListener('click', handleLogout);

        // 输入时清除错误
        emailInput.addEventListener('input', function() {
            if (this.classList.contains('error')) {
                this.classList.remove('error');
                emailError.classList.remove('show');
            }
            loginError.classList.remove('show');
        });

        passwordInput.addEventListener('input', function() {
            if (this.classList.contains('error')) {
                this.classList.remove('error');
                passwordError.classList.remove('show');
            }
            loginError.classList.remove('show');
        });

        // 页面加载时初始化
        init();
    </script>
</body>
</html>
